from pathlib import Path
import sys,json,time,numpy as np
W=Path(__file__).resolve().parents[1];sys.path.insert(0,str(W/'src'))
from reference import block,stencil,Reference,energy_stress
from apic_reference import APICReference,kinetic,momentum
from scipy.sparse import coo_matrix
R=W/'runs/formulation_serialized';R.mkdir(exist_ok=False);t0=time.monotonic();X=block(8,.0015);n=len(X);h=.003;checks={};result={};rng=np.random.default_rng(9371)
ids,w,g,grid=stencil(X,h);A=coo_matrix((w.ravel(),(np.repeat(np.arange(n),27),ids.ravel())),shape=(n,len(grid))).toarray();U,s,_=np.linalg.svd(A,full_matrices=False);rank=int((s>s[0]*1e-12).sum());z=rng.normal(size=n);z-=U[:,:rank]@(U[:,:rank].T@z);z*=.02/max(abs(z));v=np.zeros_like(X);v[:,1]=z
old=Reference(X,spacing=.0015,h=h);old.v=v.copy();old.step(1.25e-5);b=APICReference(X);b.v=v.copy();E0=kinetic(b.v,b.C,b.mass,h);b.step(1.25e-5);result['null_mode']={'old_particle_motion_m':float(np.linalg.norm(old.x-X,axis=1).max()),'old_F_change':float(np.linalg.norm(old.F-np.eye(3),axis=(1,2)).max()),'new_particle_motion_m':float(np.linalg.norm(b.x-X,axis=1).max()),'new_remaining_velocity_fraction':float(np.linalg.norm(b.v)/np.linalg.norm(v)),'initial_energy_J':E0,'recorded_transfer_loss_J':b.transfer_loss,'final_kinetic_J':kinetic(b.v,b.C,b.mass,h)};checks['null_filter']=result['null_mode']['new_remaining_velocity_fraction']<1e-8;checks['null_energy_accounted']=abs(E0-b.transfer_loss-kinetic(b.v,b.C,b.mass,h))<1e-14
for name,C in [('translation',np.zeros((3,3))),('rotation',np.array([[0,-1.,0],[1,0,0],[0,0,0]])),('affine',rng.normal(size=(3,3))*.05)]:
 b=APICReference(X);b.C[:]=C;b.v=X@C.T+[.01,-.02,.005];initial=momentum(b.x,b.v,b.C,b.mass,h);vel=b.v.copy();Fexpect=np.eye(3)+1.25e-5*C;b.step(1.25e-5);fin=momentum(b.x,b.v,b.C,b.mass,h);result[name]={'velocity_error':float(abs(b.v-vel).max()),'C_error':float(abs(b.C-C).max()),'F_error':float(abs(b.F-Fexpect).max()),'momentum_error':float(np.linalg.norm(fin[0]-initial[0])),'angular_error':float(np.linalg.norm(fin[1]-initial[1])),'transfer_loss_J':b.transfer_loss};checks[name]=max(result[name].values())<1e-11
# Independent variational force check against perturbing positions by interpolated grid virtual motion.
b=APICReference(X);b.F[:]=np.diag([1.,.99,1.]);b.x=X@b.F[0].T;b.prepare(1.25e-5);dv=rng.normal(size=(b.N,3))*.001;L=np.einsum('pki,pkj->pij',dv[b.ids],b.g);eps=1e-6;F0=b.F.copy();fd=b.vol*(energy_stress((np.eye(3)+eps*L)@F0,b.mu,b.lam)[0].sum()-energy_stress((np.eye(3)-eps*L)@F0,b.mu,b.lam)[0].sum())/(2*eps);_,P=energy_stress(F0,b.mu,b.lam);analytic=b.vol*np.sum((P@F0.transpose(0,2,1))*L);checks['internal_energy_gradient']=abs(fd-analytic)/max(abs(analytic),1e-12)<2e-5;result['internal_energy_gradient_relative']=float(abs(fd-analytic)/max(abs(analytic),1e-12))
# Contact load adjoint and force/moment balance, without particle-velocity injection.
b=APICReference(X);f=rng.normal(size=X.shape)*.0001;p0,L0=momentum(b.x,b.v,b.C,b.mass,h);b.step(1.25e-5,f);p1,L1=momentum(b.x,b.v,b.C,b.mass,h);result['external_adjoint']={'momentum_error':float(np.linalg.norm(p1-p0-1.25e-5*f.sum(0))),'angular_error':float(np.linalg.norm(L1-L0-1.25e-5*np.cross(X,f).sum(0)))};checks['external_balance']=max(result['external_adjoint'].values())<1e-12
# Projection holds the supported material points in grid degrees of freedom.
fixed=np.isclose(X[:,1],X[:,1].min());b=APICReference(X,fixed=fixed);b.step(1.25e-5,f);p1,L1=momentum(b.x,b.v,b.C,b.mass,h);result['support']={'drift_m':float(abs(b.x[fixed]-X[fixed]).max()),'speed_m_s':float(abs(b.v[fixed]).max()),'momentum_error':float(np.linalg.norm(p1-1.25e-5*f.sum(0)-b.support_impulse)),'angular_error':float(np.linalg.norm(L1-1.25e-5*np.cross(X,f).sum(0)-b.support_moment))};checks['support']=max(result['support'].values())<1e-10
# Nontrivial compatibility mixing remains conservative at common spatial nodes.
b=APICReference(X);b.codes=np.where(X[:,1]>0,np.where(X[:,0]<0,1,2),0);b.v=rng.normal(size=X.shape)*.001;b.C=rng.normal(size=(n,3,3))*.01;p0,L0=momentum(b.x,b.v,b.C,b.mass,h);b.step(1.25e-5);p1,L1=momentum(b.x,b.v,b.C,b.mass,h);result['compatible_exchange']={'momentum_error':float(np.linalg.norm(p1-p0)),'angular_error':float(np.linalg.norm(L1-L0)),'transfer_loss_J':b.transfer_loss};checks['compatible_exchange']=np.linalg.norm(p1-p0)<1e-12 and np.linalg.norm(L1-L0)<1e-12 and b.transfer_loss>=-1e-14
out={'status':'pass' if all(checks.values()) else 'fail','checks':checks,'results':result,'wall_s':time.monotonic()-t0,'scope':'Independent CPU formulation and one-step algebra; no dynamic/contact qualification'};(W/'formulation_controls.json').write_text(json.dumps(out,indent=2,default=lambda x:x.item()));print(json.dumps(out,indent=2,default=lambda x:x.item()))
